INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1001, 1, 0, "ねぇねぇ、騎士クン\n手伝ってあげようよ～", 1, 0, 0, "お！\nあそこに困ってそうな人発見！", 1.4, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 1, "春咲 ひより", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1002, 1, 0, "わ、わたし、\nなに言ってるんだろ\nあはは…", 1, 0, 0, "大切な人を\n守れるようになりたい…って", 1.4, "みんなみたいに\nわたしも強くならなきゃ", 1, "草野 優衣", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1003, 1, 0, "少しは磨かれると思いますよ。", 1, 0, 0, "キミに必要な集中力と感性が", 1.4, "フェンシングを始めてみては？", 1, "士条 怜", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1004, 1, 0, "みそぎはねぇ、\nかくれんぼやりたい！", 1, 0, 0, "今日はなにして遊ぶ？", 1.5, "ねぇ、にいちゃん！", 1, "穂高 みそぎ", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1006, 1, 0, "私といっしょに…\nいかない？", 1, 0, 0, "ねぇ…", 1.4, "風宮あかりです", 1, "風宮 あかり", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1007, 1, 0, "食べ物の恨みは怖いのー", 1, 0, 0, "プリンたべたいのー", 1.5, "出雲宮子なのー", 1, "出雲 宮子", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1008, 1, 0, "いいよ。\n見られることは運命さ…", 1, 0, 0, "キミもボクの美貌に\n吸い寄せられたんだね。", 1.4, "ボクは虹村雪。", 1, "虹村 雪", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1009, 1, 0, "人呼んで「疾風の冥姫」!!", 1, 0, 0, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 1.4, "フッ…聞いて後悔するがいい！", 1, "柊杏奈", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1010, 1, 0, "ほんまおおきにやわ～♪", 1, 0, 0, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 1.5, "マホマホ王国のプリンセス、\nまほ姫どす", 1, "姫宮 真歩", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1011, 1, 0, "ここで会ったが\n100年目～！", 1, 0, 0, "生き別れたお兄ちゃんを探して\n三千世界！", 1.4, "衣之咲璃乃です！", 1, "衣之咲 璃乃", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1012, 1, 0, "…って、お願い！\n誰にも言わないでおいて～！", 1, 0, 0, "ち、超能力って…\n何のことかな～？", 1.4, "私はハツネ、\n結構強いんだよ。\nきらーん☆", 1, "柏崎 初音", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1016, 1, 0, "ヒデサイまぢ\nGF（グッドフィーリング）～♪", 1, 0, 0, "一応カリスマ読モJKやってまっす！", 1.4, "ちょす！\n美波鈴奈だよ～♪", 1, "美波 鈴奈", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1017, 1, 0, "でも、沖縄もとってもいいとこさー", 1, 0, 0, "東京は遊園地みたいなところさー", 1.4, "はいたーい。\n喜屋武香織さー。", 1, "喜屋武 香織", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1018, 1, 0, "イオちゃんって呼んでね。", 1, 0, 0, "先生って呼ばれるのは\nくすぐったいから", 1.4, "支倉伊緒です。", 1, "支倉 伊緒", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1020, 1, 0, "ミミをおいてかないでぇ～", 1, 0, 0, "あ！/\お兄ちゃ～ん\nまってよ～", 1.5, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 1, "茜 ミミ", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1021, 1, 0, "ふぇぇぇぇぇん……", 1, 0, 0, "あの……\nふぇ……", 1.5, "あ…あの…えっと…\n栗…林…くるみ…です……", 1, "栗林 くるみ", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1022, 1, 0, "なんてありがとうございます！", 1, 0, 0, "こんな私に貴重な時間を\n割いていただき、", 1.4, "風宮よりです。\nあああああ！", 1, "風宮 より", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1023, 1, 0, "私こっち行きたいー\nね、早く早くー", 1, 0, 0, "おにいちゃんどこいくの？\nえ？", 1.5, "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 1, "北条 綾音", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1025, 1, 0, "これて何か違う…\nあああすみません！", 1, 0, 0, "ふ、不束者ですが\nどうぞ末永く…って、", 1.4, "わっ…わっ…私、\n天野すずめといいます！", 1, "天野 すずめ", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1027, 1, 0, "離しませんわ………\n絶対に…!!", 1, 0, 0, "あなたは…運命の……\n伴侶……", 1.4, "……クスクス…私は\n…倉石恵理子……", 1, "倉石 恵理子", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1028, 1, 0, "…そうでしょ？？", 1, 0, 0, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 1.4, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 1, "佐々木 咲恋", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1029, 1, 0, "あはは、\n私もまだまだだなぁ～", 1, 0, 0, "ぇっと…\nキミ、私のこと知らないの?!", 1.4, "桜井望だよ！\nよろしくねっ", 1, "桜井 望", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1030, 1, 0, "ショーグン、\nワタシと一緒に天下統一デース！", 1, 0, 0, "初めまして、\n私はニノン・ジュベール申すデス！", 1.4, "デケデケデンっ！", 1, "ニノン・ジュベール", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1031, 1, 0, "おかしいですね……", 1, 0, 0, "でもって私の隣にいるのが……\nえ、見えない？", 1.4, "上喜しのぶです。\n手元のドクロが父です。", 1, "上喜 しのぶ", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1033, 1, 0, "そう、\nオラのボケに突っ込める相方が…！", 1, 0, 0, "けんども\nそれには足りないモンが…", 1.5, "目指すはビッグな\nお笑い芸人だっぺ！", 1, "野戸まひる", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1034, 1, 0, "ちょ\nちょっと一杯飲んできます…！", 1, 0, 0, "ちょっと緊張しちゃって…", 1.4, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 1, "綾瀬 ゆかり", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1036, 1, 0, "これ以上お話しすることは…\nないです！", 1, 0, 0, "知らない人とは話しちゃいけないので", 1.5, "氷川鏡華…です", 1, "氷川 鏡華", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1038, 1, 0, "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 1, 0, 0, "……あ、アラーム。", 1.4, "柏崎…栞です。", 1, "柏崎 栞", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1040, 1, 0, "野に咲く花が、\n唯一の話相手です。", 1, 0, 0, "私、一人も友達がいなくて……", 1.4, "ふ、双葉碧です。", 1, "双葉 碧", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1042, 1, 0, "そう思っています。", 1, 0, 0, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 1.4, "三角千歌です。", 1, "三角 千歌", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1043, 1, 0, "う、疑ってすまなかったな…", 1, 0, 0, "あぁ？\nお前のそいつの仲間か？", 1.4, "安芸真琴だ。", 1, "安芸 真琴", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1044, 1, 0, "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 1, 0, 0, "生けとし生ける全ての者よ！", 1.4, "わらわこそは夜を総べる者！", 1, "イリヤ・オーンスタイン", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1045, 1, 0, "ｌク、クウカに何かご用ですか!?", 1, 0, 0, "ぐふふふふ……はっ！", 1.4, "そこで騎士は妖精を乱暴に……", 1, "遠見 空花", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1046, 1, 0, "う～ん…\n猫ってホントに最高にゃ～♪", 1, 0, 0, "自由気ままで♪\n寝て遊んで、食べてケンカして…", 1.4, "宮坂たまきにゃ♪\n猫はいいにゃよ？", 1, "宮坂たまき", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1048, 1, 0, "…と思ったら\nバイトの時間だ！\nまたあとでね！", 1, 0, 0, "それでは早速クエストに…", 1.4, "大神美冬よ！", 1, "大神 美冬", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1049, 1, 0, "お姉ちゃんがぜ～んぶ\nやってあげるからね！", 1, 0, 0, "クエストもバトルも\n掃除も洗濯も", 1.4, "星野静流だよ！", 1, "星野静流", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1050, 1, 0, "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 1, 0, 0, "見ての通りの\nセクシー美少女で", 1.5, "アタシは玉泉美咲。", 1, "玉泉美咲", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1052, 1, 0, "？？？？", 1, 0, 0, "？？？？", 1.4, "？？？", 1, "リマ", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1053, 1, 0, "そ、そこまでいうなら\nもらってやる", 1, 0, 0, "菓子でつろうなどと\n稚拙な策を……", 1.5, "モニカ・ヴァイスヴィントだ。", 1, "モニカ・ヴァイスヴィント", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1058, 1, 0, "そ、そこまでいうなら\nもらってやる", 1, 0, 0, "菓子でつろうなどと\n稚拙な策を……", 1.5, "モニカ・ヴァイスヴィントだ。", 1, "ペコリーヌ", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1059, 1, 0, "そ、そこまでいうなら\nもらってやる", 1, 0, 0, "菓子でつろうなどと\n稚拙な策を……", 1.5, "モニカ・ヴァイスヴィントだ。", 1, "コッコロ", 2, 0, 0);
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1060, 1, 0, "そ、そこまでいうなら\nもらってやる", 1, 0, 0, "菓子でつろうなどと\n稚拙な策を……", 1.5, "モニカ・ヴァイスヴィントだ。", 1, "キャル", 2, 0, 0);
